// Jotform manda los datos como multipart/form-data.
// El campo "pretty" trae todas las preguntas y respuestas ya formateadas y legibles.
const body = $input.first().json.body || {};

let qa = body.pretty || 'No se recibieron respuestas legibles (revisar payload).';

// Limpieza básica: separar por comas de nivel superior no es 100% seguro,
// así que dejamos el texto de "pretty" tal cual lo entrega Jotform.
qa = decodeURIComponent(qa.replace(/\+/g, ' '));

return [
  {
    json: {
      qa_texto: qa,
      submissionID: body.submissionID || '',
      formID: body.formID || '',
      formTitle: body.formTitle || 'Diagnóstico de Facturación y Proveedores — AIE Constructora'
    }
  }
];
